#!/bin/sh
# Generated by sshfs.nvim (lib/git_route.lua); regenerated on every setup, do not edit.
#
# Runs read-mostly git commands for paths under an sshfs mount on the remote host
# over the existing ControlMaster connection, instead of walking the tree over FUSE.
# Anything it cannot translate faithfully runs the real git unchanged.

REAL_GIT=@REAL_GIT@
MAP_DIR=@MAP_DIR@

ssh_to_host() {
  ssh @SSH_OPTIONS@ "$@"
}

# Quote $1 for a POSIX remote shell into QUOTED, without spawning a process.
quote() {
  _rest=$1
  _out=
  while :; do
    case $_rest in
      *\'*)
        _out="$_out${_rest%%\'*}'\\''"
        _rest=${_rest#*\'}
        ;;
      *) break ;;
    esac
  done
  QUOTED="'$_out$_rest'"
}

# True when $1 is $2 or lies below it.
under() {
  case $1 in
    "$2" | "$2"/*) return 0 ;;
  esac
  return 1
}

# True when $1 has no empty, "." or ".." segments, so lexical translation is exact.
plain_path() {
  _p=$1
  case $_p in
    / | "") return 0 ;;
    */) _p=${_p%/} ;;
  esac
  case "/${_p#/}/" in
    */../* | */./* | *//*) return 1 ;;
  esac
  return 0
}

# Select the mount whose local path (logical or physical) is the longest prefix of $1.
find_mount() {
  M_FOUND=
  _best=-1
  for _f in "$MAP_DIR"/*.map; do
    [ -f "$_f" ] || continue
    _mount= _real_mount= _host= _user= _port= _remote= _real=
    while IFS= read -r _line || [ -n "$_line" ]; do
      case $_line in
        mount=*) _mount=${_line#mount=} ;;
        real_mount=*) _real_mount=${_line#real_mount=} ;;
        host=*) _host=${_line#host=} ;;
        user=*) _user=${_line#user=} ;;
        port=*) _port=${_line#port=} ;;
        remote=*) _remote=${_line#remote=} ;;
        real=*) _real=${_line#real=} ;;
      esac
    done <"$_f"
    [ -n "$_mount" ] && [ -n "$_host" ] && [ -n "$_remote" ] || continue
    for _cand in "$_mount" "$_real_mount"; do
      [ -n "$_cand" ] || continue
      under "$1" "$_cand" || continue
      if [ "${#_cand}" -gt "$_best" ]; then
        _best=${#_cand}
        M_FOUND=1
        M_MOUNT=$_mount
        M_REAL_MOUNT=$_real_mount
        M_HOST=$_host
        M_USER=$_user
        M_PORT=$_port
        M_REMOTE=$_remote
        M_REAL=$_real
      fi
    done
  done
  [ -n "$M_FOUND" ]
}

# Translate local path $1 (under the selected mount) to REMOTE_PATH.
to_remote() {
  plain_path "$1" || return 1
  for _cand in "$M_MOUNT" "$M_REAL_MOUNT"; do
    [ -n "$_cand" ] || continue
    if under "$1" "$_cand"; then
      _rest=${1#"$_cand"}
      REMOTE_PATH=${M_REMOTE%/}$_rest
      [ -n "$REMOTE_PATH" ] || REMOTE_PATH=/
      return 0
    fi
  done
  return 1
}

# Absolute form of $1, relative paths being relative to DIR.
absolute() {
  case $1 in
    /*) ABS_PATH=$1 ;;
    *) ABS_PATH=${DIR%/}/$1 ;;
  esac
}

TMP_OUT=
cleanup() {
  [ -z "$TMP_OUT" ] || rm -f "$TMP_OUT"
}
trap cleanup EXIT
trap 'cleanup; exit 143' TERM
trap 'cleanup; exit 130' INT
trap 'cleanup; exit 129' HUP

# Returns 0 with ROUTE_RC set when the command ran remotely, 1 when the real git must run.
# Every decision to fall back is made before any stdin is consumed or caller-visible output is
# produced, so the real git never repeats work visibly: once ssh is running its exit status, 255
# included, is final. (Output the mount cannot express falls back after the remote command ran,
# but its output was only buffered.)
route() {
  # An interactive terminal wants git's own colour and pager, which a remote pipe cannot give.
  [ ! -t 1 ] || return 1

  # Variables that redirect git to local files cannot be mirrored remotely.
  for _name in GIT_DIR GIT_INDEX_FILE GIT_WORK_TREE GIT_COMMON_DIR GIT_OBJECT_DIRECTORY \
    GIT_ALTERNATE_OBJECT_DIRECTORIES GIT_NAMESPACE GIT_CONFIG GIT_CONFIG_GLOBAL \
    GIT_CONFIG_SYSTEM GIT_CONFIG_COUNT GIT_EXTERNAL_DIFF GIT_ATTR_SOURCE; do
    eval "[ -z \"\${$_name+x}\" ]" || return 1
  done

  DIR=$(pwd -P) || return 1
  GIT_DIR_ARG=
  WORK_TREE_ARG=
  GLOBALS=
  while [ $# -gt 0 ]; do
    case $1 in
      -C)
        [ $# -ge 2 ] || return 1
        case $2 in
          "" | .) ;;
          *)
            absolute "$2"
            DIR=$ABS_PATH
            ;;
        esac
        shift 2
        ;;
      -c)
        [ $# -ge 2 ] || return 1
        quote "$2"
        GLOBALS="$GLOBALS -c $QUOTED"
        shift 2
        ;;
      --git-dir=*)
        GIT_DIR_ARG=${1#*=}
        shift
        ;;
      --git-dir)
        [ $# -ge 2 ] || return 1
        GIT_DIR_ARG=$2
        shift 2
        ;;
      --work-tree=*)
        WORK_TREE_ARG=${1#*=}
        shift
        ;;
      --work-tree)
        [ $# -ge 2 ] || return 1
        WORK_TREE_ARG=$2
        shift 2
        ;;
      --no-pager | --no-optional-locks | --literal-pathspecs | --glob-pathspecs | \
        --noglob-pathspecs | --icase-pathspecs | --no-replace-objects)
        GLOBALS="$GLOBALS $1"
        shift
        ;;
      -*) return 1 ;;
      *) break ;;
    esac
  done
  [ $# -ge 1 ] || return 1

  SUB=$1
  shift
  TRANSLATE_OUTPUT=
  TRANSLATE_SPACE=
  TRANSLATE_WORKTREE=
  NEEDS_STDIN=
  case $SUB in
    rev-parse) TRANSLATE_OUTPUT=1 ;;
    ls-files | ls-tree | diff | show | cat-file | log | blame | status | check-attr | hash-object | \
      update-index | for-each-ref | symbolic-ref | merge-base | rev-list) ;;
    apply)
      NEEDS_STDIN=1
      _cached=
      for _a in "$@"; do
        case $_a in
          --cached) _cached=1 ;;
          -) ;;
          -*) ;;
          *) return 1 ;;
        esac
      done
      [ -n "$_cached" ] || return 1
      ;;
    config)
      _get=
      for _a in "$@"; do
        case $_a in
          --get | --get-all | --get-regexp | --get-urlmatch | --get-color | --get-colorbool) _get=1 ;;
          --global | --system | -f | --file | --file=* | --blob | --blob=* | --worktree) return 1 ;;
        esac
      done
      [ -n "$_get" ] || return 1
      ;;
    worktree)
      [ "$1" = list ] || return 1
      TRANSLATE_OUTPUT=1
      TRANSLATE_SPACE=1
      TRANSLATE_WORKTREE=1
      for _a in "$@"; do
        [ "$_a" != -z ] || return 1
      done
      ;;
    *) return 1 ;;
  esac

  DIR=${DIR%/}
  [ -n "$DIR" ] || DIR=/
  find_mount "$DIR" || return 1
  to_remote "$DIR" || return 1
  quote "$REMOTE_PATH"
  QDIR=$QUOTED

  GIT_PATH_ARGS=
  if [ -n "$GIT_DIR_ARG" ]; then
    absolute "$GIT_DIR_ARG"
    to_remote "$ABS_PATH" || return 1
    quote "$REMOTE_PATH"
    GIT_PATH_ARGS="$GIT_PATH_ARGS --git-dir $QUOTED"
  fi
  if [ -n "$WORK_TREE_ARG" ]; then
    absolute "$WORK_TREE_ARG"
    to_remote "$ABS_PATH" || return 1
    quote "$REMOTE_PATH"
    GIT_PATH_ARGS="$GIT_PATH_ARGS --work-tree $QUOTED"
  fi

  RARGS=
  _expect_contents=
  for _a in "$@"; do
    if [ -n "$_expect_contents" ]; then
      _expect_contents=
      [ "$_a" = - ] || return 1
    fi
    case $_a in
      --no-index | -F | --file | --file=* | --output | --output=* | --exclude-from | --exclude-from=* | \
        -X | -O* | --open-files-in-pager*)
        return 1
        ;;
      --contents) _expect_contents=1 NEEDS_STDIN=1 ;;
      --contents=*) return 1 ;;
      --stdin | --stdin-paths | --index-info | --batch | --batch=* | --batch-check | --batch-check=* | \
        --batch-command | --batch-command=*)
        NEEDS_STDIN=1
        ;;
    esac
    # A relative path that climbs out of the work dir would resolve remotely, not locally.
    case $_a in
      .. | ../* | */../* | */..) return 1 ;;
    esac
    _prefix=
    _value=$_a
    case $_a in
      --*=/*)
        _prefix=${_a%%=*}=
        _value=${_a#*=}
        ;;
    esac
    case $_value in
      /*)
        to_remote "$_value" || return 1
        _value=$REMOTE_PATH
        ;;
    esac
    quote "$_prefix$_value"
    RARGS="$RARGS $QUOTED"
  done
  [ -z "$_expect_contents" ] || return 1

  _env=
  if [ -n "${LC_ALL+x}" ]; then
    quote "$LC_ALL"
    _env="$_env LC_ALL=$QUOTED"
  fi
  if [ -n "${GIT_OPTIONAL_LOCKS+x}" ]; then
    quote "$GIT_OPTIONAL_LOCKS"
    _env="$_env GIT_OPTIONAL_LOCKS=$QUOTED"
  fi
  quote "$SUB"
  _remote_cmd="cd $QDIR && exec env$_env git$GLOBALS$GIT_PATH_ARGS $QUOTED$RARGS"

  set -- -o LogLevel=QUIET
  [ -z "$M_PORT" ] || set -- "$@" -p "$M_PORT"
  [ -z "$M_USER" ] || set -- "$@" -l "$M_USER"

  # Local-only probe of the mount's ControlMaster socket: a missing socket would otherwise cost a
  # full handshake (or the connect timeout) on every call.
  ssh_to_host -n "$@" -O check "$M_HOST" >/dev/null 2>&1 || return 1

  [ -n "$NEEDS_STDIN" ] || set -- -n "$@"

  if [ -z "$TRANSLATE_OUTPUT" ]; then
    exec ssh @SSH_OPTIONS@ "$@" "$M_HOST" "$_remote_cmd"
  fi

  TMP_OUT=$(mktemp) || return 1
  ssh_to_host "$@" "$M_HOST" "$_remote_cmd" >"$TMP_OUT"
  ROUTE_RC=$?
  # Absolute output the mount cannot express (repo root above a subdirectory mount, gitdir or
  # worktree elsewhere, symlink target) would hand callers nonexistent paths: let local git answer.
  L_LOCAL=$M_MOUNT L_REAL=$M_REAL L_LOGICAL=$M_REMOTE L_SPACE=$TRANSLATE_SPACE L_WORKTREE=$TRANSLATE_WORKTREE awk '
    function translate(line, prefix,    n) {
      sub(/\/$/, "", prefix)
      n = length(prefix)
      if (length(line) == 0 || substr(line, 1, n) != prefix) return ""
      if (length(line) == n || substr(line, n + 1, 1) == "/" || (ENVIRON["L_SPACE"] != "" && substr(line, n + 1, 1) == " "))
        return ENVIRON["L_LOCAL"] substr(line, n + 1)
      return ""
    }
    {
      head = ""
      body = $0
      if (ENVIRON["L_WORKTREE"] != "" && substr(body, 1, 9) == "worktree ") {
        head = "worktree "
        body = substr(body, 10)
      }
      out = ""
      if (ENVIRON["L_REAL"] != "") out = translate(body, ENVIRON["L_REAL"])
      if (out == "") out = translate(body, ENVIRON["L_LOGICAL"])
      if (out == "" && substr(body, 1, 1) == "/") bad = 1
      lines[NR] = head (out != "" ? out : body)
    }
    END {
      if (bad) exit 3
      for (i = 1; i <= NR; i++) print lines[i]
    }' "$TMP_OUT"
  [ $? -ne 3 ] || return 1
  return 0
}

if route "$@"; then
  exit "$ROUTE_RC"
fi
cleanup
exec "$REAL_GIT" "$@"
